  @Param
  onTap: (() => void) | undefined = undefined;

  /**
   * 构建通用图标
   * @returns {void} 无返回值
   */
  build(): void {
    if (this.tintColor !== undefined) {
      Image(this.icon)
        .width(this.iconSize)
        .height(this.iconSize)
        .fillColor(this.tintColor)
        .onClick((): void => this.handleTap());
    } else {
      Image(this.icon)
        .width(this.iconSize)
        .height(this.iconSize)
        .onClick((): void => this.handleTap());
    }
  }

  /**
   * 处理点击事件
   * @returns {void} 无返回值
   */
  private handleTap(): void {
    if (this.onTap) {
